using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool, Description("Fetches a post by ID from the external API.")]
    public static async Task<string> GetPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric ID of the post to retrieve.")] int id,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("api");
        var post = await client.GetFromJsonAsync<JsonElement>(
            $"/posts/{id}", cancellationToken);
        return post.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerPromptType]
public sealed class SummarizePrompts
{
    [McpServerPrompt, Description("Creates a summarization prompt for the given text.")]
    public static ChatMessage Summarize(
        [Description("The text to summarize.")] string text)
    {
        return new ChatMessage(
            ChatRole.User,
            $"Please provide a concise summary of the following text:\n\n{text}");
    }
}

